  // Written numeral systems supported by the app. A language may still have
  // translated words but, if it is not listed here, age copy deliberately
  // falls back to English so a spoken-only language is never shown with an
  // arbitrary or misleading numeral system.
  static const _writtenNumberSystems = <String, String>{
    'ur': 'arabicIndic',
    'pa': 'western',
    'sd': 'arabicIndic',
    'en': 'western',
    'ar': 'arabicIndic',
