  static final locale = ValueNotifier<Locale>(languages.first.locale);
  static final selectedCode = ValueNotifier<String>(languages.first.code);

  /// Base state class for screens that use translated strings in properties
  /// such as labels, hints, titles, and tooltips. LocalizedText listens on its
  /// own, while this class makes the rest of each screen rebuild immediately
  /// when the language changes.
  static void addListener(VoidCallback listener) =>
      selectedCode.addListener(listener);
  static void removeListener(VoidCallback listener) =>
      selectedCode.removeListener(listener);

  static AppLanguage get selected => languages.firstWhere(
    (language) => language.code == selectedCode.value,
    orElse: () => languages.first,
  );

  static Future<void> load() async {
    final preferences = await SharedPreferences.getInstance();
    final code = preferences.getString(preferenceKey);
    if (code == null) return;

    final saved = languages.where((language) => language.code == code);
    if (saved.isNotEmpty) {
      selectedCode.value = saved.first.code;
      locale.value = saved.first.locale;
    }
  }

  static Future<void> setLanguage(AppLanguage language) async {
    // Notify the UI before touching disk. The selector and every listening
    // localized widget must change in the same frame, even if preferences
    // storage is slow or temporarily unavailable.
    selectedCode.value = language.code;
    locale.value = language.locale;

    try {
      final preferences = await SharedPreferences.getInstance();
      await preferences.setString(preferenceKey, language.code);
    } catch (_) {
      // A storage failure must not delay or undo the visible language change.
    }
  }

  /// Formats an age using the numeral system supported by the selected app
  /// language. Unknown/spoken-only language codes intentionally use English.
  static String formatAgeNumber(int value) {
    return formatNumber(value);
  }

  /// Formats a number using the selected language's written numeral system.
  /// Unknown/spoken-only language codes intentionally use English digits.
  static String formatNumber(int value) {
    final system = _writtenNumberSystems[selectedCode.value];
    if (system == null || system == 'western') return value.toString();

    if (system == 'chinese') {
      const digits = <int, String>{
        0: '〇',
        1: '一',
        2: '二',
        3: '三',
        4: '四',
        5: '五',
        6: '六',
        7: '七',
        8: '八',
        9: '九',
      };
      if (value < 10) return digits[value] ?? value.toString();
      if (value < 20) return '十${value == 10 ? '' : digits[value - 10]}';
      if (value < 100) {
        final tens = value ~/ 10;
        final ones = value % 10;
        return '${tens == 1 ? '' : digits[tens]}十${ones == 0 ? '' : digits[ones]}';
      }
      return value.toString();
    }

    const systems = <String, String>{
      'arabicIndic': '٠١٢٣٤٥٦٧٨٩',
      'persian': '۰۱۲۳۴۵۶۷۸۹',
      'devanagari': '०१२३४५६७८९',
      'bengali': '০১২৩৪৫৬৭৮৯',
    };
    final digits = systems[system];
    if (digits == null) return value.toString();
    return value.toString().split('').map((digit) {
      return String.fromCharCode(digits.runes.elementAt(int.parse(digit)));
    }).join();
  }

  /// Keeps stored heights canonical (for example 5'7") while displaying
  /// their feet and inches with the selected language's numerals.
  static String formatHeight(String value) {
    final separator = value.indexOf("'");
    if (separator <= 0) return value;
    final feet = int.tryParse(value.substring(0, separator));
    final inches = int.tryParse(
      value.substring(separator + 1).replaceAll('"', ''),
    );
    if (feet == null || inches == null) return value;
    return "${formatNumber(feet)}'${formatNumber(inches)}\"";
  }

  static String translateAge(String value, {int age = 18}) {
    final code = _writtenNumberSystems.containsKey(selectedCode.value)
        ? selectedCode.value
        : 'en';
    final template = value == '{age} years'
        ? (_ageUnitCopy[code] ?? _ageUnitCopy['en']!)
        : _ageCopy[code]?[value] ?? _ageCopy['en']![value] ?? value;
    return template.replaceAll('{age}', formatAgeNumber(age));
  }

