    final moderationTranslation = moderationCopy[selectedCode.value]?[value];
    if (moderationTranslation != null) return moderationTranslation;

    final apiAuthTranslation = _apiAuthCopy[selectedCode.value]?[value];
    if (apiAuthTranslation != null) return apiAuthTranslation;

    final authTranslation = _authCopy[selectedCode.value]?[value];
    if (authTranslation != null) return authTranslation;

    if (value == 'Minimum Education') {
      return minimumEducation[selectedCode.value] ?? value;
    }

    if (_ageCopy.values.any((copy) => copy.containsKey(value))) {
      return translateAge(value);
    }

    return recoveryCopy[selectedCode.value]?[value] ??
        sessionCopy[selectedCode.value]?[value] ??
        privacyCopy[selectedCode.value]?[value] ??
        verificationCopy[selectedCode.value]?[value] ??
        discoveryCopy[selectedCode.value]?[value] ??
        _welcomeCopy[selectedCode.value]?[value] ??
        _copy[selectedCode.value]?[value] ??
        _internationalCopy[selectedCode.value]?[value] ??
        _tabCopy[selectedCode.value]?[value] ??
        _profileCopy[selectedCode.value]?[value] ??
        value;
  }

  static String translateTemplate(
    String template,
    Map<String, Object?> substitutions,
  ) {
    var result = translate(template);
    for (final entry in substitutions.entries) {
      result = result.replaceAll(
        '{${entry.key}}',
        entry.value?.toString() ?? '',
      );
    }
    return result;
  }
}

abstract class LanguageAwareState<T extends StatefulWidget> extends State<T> {
  void _languageChanged() {
    if (mounted) setState(() {});
  }

  @override
  void initState() {
    super.initState();
    AppLanguageService.addListener(_languageChanged);
  }

  @override
  void dispose() {
    AppLanguageService.removeListener(_languageChanged);
    super.dispose();
  }
}
